/* Only local public assets are cached. Never cache admin, authentication,
   Firestore, submissions, runtime config or cross-origin responses. */
const VERSION='isew-public-v5';
const ASSETS=['/index.html','/courses.html','/about.html','/journal.html','/contact.html','/faq.html','/styles.css','/app.js','/ui.js','/richtext.js','/experience.js','/backend.js','/catalog.json','/posts.json','/settings.json','/site.webmanifest','/android-chrome-192x192.png','/android-chrome-512x512.png','/assets/brand/logo.png','/assets/hero/hero-1.jpg'];
self.addEventListener('install',event=>event.waitUntil(caches.open(VERSION).then(cache=>cache.addAll(ASSETS)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith('isew-public-')&&key!==VERSION).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin||url.pathname.includes('admin')||url.pathname==='/runtime-config.js'||url.pathname.startsWith('/api/')||!(/\.(html|css|js|json|jpg|png|webp|ico)$/.test(url.pathname)||url.pathname==='/'))return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();event.waitUntil(caches.open(VERSION).then(cache=>cache.put(event.request,copy)));}return response;}).catch(async()=>await caches.match(event.request)||new Response('You are offline. Reconnect to open this page.',{status:503,headers:{'Content-Type':'text/plain'}})));});
